    for s, t in zip(S, T):
        if s in F:
            if F[s] != t:
                print(-1)
                return
        else:
            F[s] = t

    A = set(S)
    image = set(F.values())

    # Impossible case: F is a bijection on all 26 letters. 
    # Since S != T, there is at least one cycle of length >= 2, 
    # but we don't have a free temporary character to break it.
    if len(image) == 26:
        print(-1)
        return

    edges = sum(1 for c in A if F[c] != c)

    nodes = A | image
    indeg = {c: 0 for c in nodes}
    for u in A:
        indeg[F[u]] += 1

    parent = {c: c for c in nodes}

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    for u in A:
        pu = find(u)
        pv = find(F[u])
        if pu != pv:
            parent[pu] = pv

    comp_nodes = {}
    for node in nodes:
        p = find(node)
        if p not in comp_nodes:
            comp_nodes[p] = []
        comp_nodes[p].append(node)

    pure_cycles = 0
    for p, comp in comp_nodes.items():
        # A component requires an extra breaking operation ONLY if it is a pure cycle of length >= 2.
        # It's a pure cycle if and only if NO node in the component has an in-degree of 0.
        if len(comp) >= 2:
            if all(indeg[node] > 0 for node in comp):
                pure_cycles += 1

    print(edges + pure_cycles)

